[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-neurology",
  "answer": "70세 편측 안정 시 진전+서동은 특발성 파킨슨병(IPD)이 가장 가능성이 높지만, 6개월 내 진행 속도·자세 불안정·자율신경·안구운동·인지·좌우 비대칭성 소견을 확인해 PSP·MSA·CBD·혈관성 파킨슨증을 먼저 배제해야 합니다. 70대 초기 약물 선택은 운동합병증(이상운동증)보다 자세 불안정·인지·자율신경·정신증 위험을 우선 고려하여, 다른 금기가 없으면 레보도파를 저용량부터 시작하는 쪽이 일반적으로 선호되고 도파민작용제는 신중 검토 대상입니다. 다만 이는 진단 확정 이후의 결정이며, 처방은 대면 진료에서 확정되어야 합니다.",
  "red_flag": {
    "present": false,
    "items": []
  },
  "hypotheses": [
    {
      "name": "특발성 파킨슨병 (Idiopathic Parkinson disease)",
      "icd10": "G20",
      "must_not_miss": false,
      "probability_band": "high",
      "supports": [
        { "text": "편측성 안정 시 진전 + 서동의 조합은 IPD의 핵심 운동증상 조합", "basis": "history" },
        { "text": "6개월에 걸친 점진적 경과, 70세 남성이라는 연령·성별 분포 부합", "basis": "history" }
      ],
      "against": [
        { "text": "좌우 대칭성·축성 증상 우세·자세 불안정이 초기부터 두드러지면 비정형 파킨슨증후군 쪽으로 기움", "basis": "history" },
        { "text": "레보도파 반응 여부·정도가 확인되지 않음", "basis": "history" }
      ]
    },
    {
      "name": "진행성 핵상 마비 (Progressive supranuclear palsy, PSP)",
      "icd10": "G23.1",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "70세 남성, 파킨슨증상의 축성(자세·보행·균형) 우세 가능성", "basis": "history" },
        { "text": "초기부터 넘어짐·후방으로 쓰러짐이 있으면 PSP 가능성 상승", "basis": "history" }
      ],
      "against": [
        { "text": "편측성 진전이 두드러진다는 소견은 PSP의 대칭성·무진전 양상과 다소 어긋남", "basis": "history" },
        { "text": "수직 안구운동 제한·안구운동 실행증·가성구마비 확인되지 않음", "basis": "history" }
      ]
    },
    {
      "name": "다계통 위축 (Multiple system atrophy, MSA)",
      "icd10": "G23.2",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "자율신경 증상(기립성 저혈압, 배뇨장애, 변비, 발한 이상) 동반 시 MSA 가능성", "basis": "history" }
      ],
      "against": [
        { "text": "안정 시 진전이 초기 주 증상이라는 점은 MSA에서 상대적으로 드묾", "basis": "history" },
        { "text": "기립성 저혈압·배뇨·REM 수면행동장애 등 자율신경 소견 확인되지 않음", "basis": "history" }
      ]
    },
    {
      "name": "피질기저핵 변성 (Corticobasal degeneration, CBD)",
      "icd10": "G31.85",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "편측성 증상 우세는 CBD에서 흔한 양상이나, 증상의 성격이 진전·서동이라는 점에서 다름", "basis": "history" }
      ],
      "against": [
        { "text": "CBD의 특징인 이상 사지 현상(외계 사지), 피질성 감각 소실, 실행증, 반사성 근간대 확인되지 않음", "basis": "history" },
        { "text": "레보도파 반응 저하·비대칭성 피질징후가 보고되지 않음", "basis": "history" }
      ]
    },
    {
      "name": "혈관성 파킨슨증 (Vascular parkinsonism)",
      "icd10": "G21.4",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "고혈압·당뇨·심방세동 등 혈관 위험인자가 있으면 가능성 상승", "basis": "history" }
      ],
      "against": [
        { "text": "하지 우세 보행장애·계단 걸음·초기 균형장애 중심 양상이 아니고, 편측 진전 우세라는 점에서 다름", "basis": "history" },
        { "text": "뇌영상(기저핵 다발성 열공경색 등) 확인되지 않음", "basis": "history" }
      ]
    }
  ],
  "missing_info": [
    "초기부터 넘어짐·뒤로 쓰러짐이 있었습니까? (또는 보행 시작 시 계단걸음·동결보행 여부)"
  ],
  "suggested_tests": [
    { "name": "신경학적 진찰(안구운동·축성 근긴장·자세반사·피질징후 포함)", "purpose": "PSP·CBD 등 비정형 파킨슨증후군 감별", "urgency": "routine", "basis": "guideline" },
    { "name": "뇌 MRI(가능하면 SWI·T2* 포함)", "purpose": "혈관성 병변·중뇌 위축(벌새새 모양)·기저핵 신호 변화 평가", "urgency": "routine", "basis": "guideline" },
    { "name": "자율신경 평가(기립 시 혈압·맥박, 배뇨·배변력) 및 REM 수면행동장애 병력 청취", "purpose": "MSA 감별", "urgency": "routine", "basis": "guideline" },
    { "name": "도파민 운반체 영상(DAT SPECT/PET) — 선택적", "purpose": "기능적 도파민 결손 확인(진단 불확실 시)", "urgency": "routine", "basis": "guideline" },
    { "name": "인지기능 선별검사(MMSE/MoCA) 및 정신증 선별", "purpose": "치료 선택 및 약물 부작용 위험 평가", "urgency": "routine", "basis": "guideline" }
  ],
  "suggested_treatments": [
    {
      "kind": "referral",
      "description": "파킨슨병 및 파킨슨증후군 감별은 신경과 대면 진료에서 확정. 위 감별 소견이 정리되기 전에는 약물 시작을 보류할 것을 권고.",
      "basis": "guideline"
    },
    {
      "kind": "prescription_drug",
      "description": "특발성 파킨슨병으로 확정된 경우, 70대 초반은 인지·자세불안정·자율신경·정신증 위험을 우선 고려. 다른 금기가 없으면 레보도파를 저용량부터 시작하고, 도파민작용제는 부작용(졸림·충동조절장애·환각·기립성 저혈압)과 인지 위험을 감안하여 신중 검토. 구체적 약물·용량·증량 일정은 대면 진료에서 결정.",
